from typing import List

def split_identifier(name: str) -> List[str]:
    '''Split identifier into lowercase words.'''
    s = name
    for c in '_-.':
        s = s.replace(c, ' ')
    res = []
    for i, char in enumerate(s):
        if i > 0 and (s[i-1].islower() or s[i-1].isdigit()) and char.isupper():
            res.append(' ')
        res.append(char)
    return [w.lower() for w in ''.join(res).split() if w]"
