    if not line: return [""]
    fields, i, n = [], 0, len(line)
    while i < n:
        j = i
        while j < n and line[j] == ' ':
            j += 1
        if j < n and line[j] == '"':
            content, i = [], j + 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i+1] == '"':
                        content.append('"'); i += 2
                    else:
                        i += 1; break
                else:
                    content.append(line[i]); i += 1
            else: raise ValueError("Unterminated quote")
            while i < n and line[i] == ' ':
                i += 1
            if i < n and line[i] != delimiter: raise ValueError("Text after quote")
            fields.append("".join(content))
            if i < n and line[i] == delimiter: i += 1
        else:
            start = i
            while i < n and line[i] != delimiter: i += 1
            f = line[start:i]
            if f: fields.append(f)
            if i < n and line[i] == delimiter: i += 1
            else: break
    return fields"}}, "messages": []}

